/* Needs <xc.h> on the PIC. Here PORTB is a variable, so the loop runs anywhere. */
#include <stdio.h>

static unsigned char PORTB;

int main(void) {
    unsigned char pattern[4] = {0x3F, 0x06, 0x5B, 0x4F};
    unsigned char i = 0;
    int step;
    for (step = 0; step < 8; step++) {
        PORTB = pattern[i];
        printf("%02X\n", PORTB);
        i = (i + 1) % 4;
    }
    return 0;
}
